readEffectiveStreamHead: (stream) => {
  const store = new SQLiteEventHistoryBranchStore(
    getSQLiteService().getDatabase(),
  );
  const effective = store.requireEffectiveHead(stream);
  const branch = store.requireBranch(stream, effective.branchId);
  return {
    branchId: effective.branchId,
    revision: branch.baseRevision,
    digest: branch.baseDigest,
  };
},

