readEffectiveStreamHead: (stream) => {
  const key = `${stream.streamType}/${stream.streamId}`;
  const cached = STALE_HEADS.get(key);
  if (cached !== undefined) return cached;
  const db = getSQLiteService().getDatabase();
  const fresh = readEffectiveStreamHead(
    db,
    new SQLiteEventHistoryBranchStore(db),
    stream,
  );
  STALE_HEADS.set(key, fresh);
  return fresh;
},
